import { useMemo } from 'react';
import { CommonResolutions, } from '..';
import { VisionCamera } from '../VisionCamera';
export function useVideoOutput({ targetResolution = CommonResolutions.FHD_16_9, targetBitRate, enablePersistentRecorder, enableAudio, } = {}) {
    const videoOutput = useMemo(() => VisionCamera.createVideoOutput({
        targetResolution: targetResolution,
        targetBitRate: targetBitRate,
        enablePersistentRecorder: enablePersistentRecorder,
        enableAudio: enableAudio,
    }), [enablePersistentRecorder, targetBitRate, enableAudio, targetResolution]);
    return videoOutput;
}
